style.css:
@-moz-document domain("roblox.com") {
/* Background Image */
    body, .content, .nav-content-inner, .container-main, #MasterContainer, #wrap > div.container-main > div {
        background: url("https://i.imgur.com/J4XjXrs.jpg") top center no-repeat !important;
        background-size: cover !important;
        background-attachment: fixed !important;
    }
    
    /* Remove Ads */
    .ad, .ad *, .img_ad, .ad-annotations, #google_image_div, #aw0, #AdvertisingLeaderboard,
    #TopAbpContainer, #LeftGutterAdContainer, #RightGutterAdContainer, #Skyscraper-Adp-Right, #Skyscraper-Adp-Left,
    .abp-spacer, .sponsored-game, .alert-info, .gutter-ads {
        display: none !important;
    }
    
    /* Customize Header and UI Elements */
    #header, .navigation .notification-icon, .rbx-highlight, #chat-header, .slide-item-container-left, .profile-avatar-right {
        background: #ffffff !important;
    }
    
    /* Buttons and Highlights */
    .rbx-upgrade-now #upgrade-now-button, .rbx-btn-secondary-xs.btn-more, .rbx-vip-server-create, .btn-secondary-xs {
        background-color: #ffffff !important;
        border-color: #ffffff !important;
    }
    
    .rbx-upgrade-now #upgrade-now-button:hover, .rbx-btn-secondary-xs.btn-more:hover, .rbx-vip-server-create:hover, .btn-secondary-xs:hover {
        background: #e3e3e3 !important;
        border-color: #e3e3e3 !important;
    }
    
    /* Text Adjustments */
    h1, h2, .game-card-name, .item-card-name, .friend-name, .text-name, .text-robux-lg {
        color: black !important;
    }
    
    /* Profile and Avatar Transparency */
    .profile-avatar-left, #tab-wardrobe, #characterInventorySearch, #tab-outfits, #HomeContainer > div.col-xs-12.home-header > a {
        background: transparent !important;
    }
}
